class NoSQLStore:
    def connect(self):
        return 'nosql'

    def find(self, query):
        return self.connect() + ':' + str(query)

files.services/orders.py:
from db.store import NoSQLStore


class OrderService:
    def __init__(self):
        self.store = NoSQLStore()

    def total(self):
        return self.store.find({'agg': 'sum', 'field': 'amount'})

    def legacy_total(self):
        from db.store import MySQLStore
        return MySQLStore().query('select sum(amount) from orders')
